/-- Project a bounded-outcome model to its graph component. -/
def toGraphClass (M : BddOutcomeModelClass V d β B) : GraphClass V d :=
  { edge := M.edge, decEdge := M.decEdge, degree_le := M.degree_le }

/-- The standing degree-index restriction `d ≤ n = |V|`. -/
def DegreeIndex (V : Type*) [Fintype V] (d : ℕ) : Prop :=
  d ≤ Fintype.card V

/-- Project a model to its coefficient schedule. -/
def toCoeffClass (M : ModelClass V d β B) : CoeffClass M.edge β B :=
  { coef := M.coef
    supported := M.supported
    low_order := M.low_order
    mass_le := M.mass_le }

/-- Project a model to its bounded-degree graph. -/
def toGraphClass (M : ModelClass V d β B) : GraphClass V d :=
  { edge := M.edge, decEdge := M.decEdge, degree_le := M.degree_le }

/-- A nonconstant interaction order in `{1,...,min β d}`. -/
def OrderIndex (β d r : ℕ) : Prop :=
  1 ≤ r ∧ r ≤ effBeta β d

/-- Measurability in the outcome vector, with graph and assignment fixed. -/
def OutcomeMeasurable (est : Estimator V) : Prop :=
  ∀ G z, Measurable (fun y : V → ℝ => est G z y)

/-- Feasibility for the normalized perturbation program. -/
def PerturbFeasible (β d : ℕ) (h : (Fin d → Bool) → ℝ) : Prop :=
  h ∈ polySpace β d ∧ contrastFunctional h = 1

/-- The Bernoulli contrast `(1-p)^r - (-p)^r`. -/
def bernoulliContrast (p : ℝ) (r : ℕ) : ℝ :=
  (1 - p) ^ r - (-p) ^ r

/-- Defines block baseline support. -/
def blockBaselineSupport (B : ℝ) {m : ℕ} (U : Fin m → ℝ) : Prop :=
  ∀ b, |U b| ≤ B / 2

/-- The complete directed block graph, including loops, on active units;
inactive units are isolated. -/
def blockGraph (n d : ℕ) (j i : Fin n) : Prop :=
  j.val < activeCount n d ∧ i.val < activeCount n d ∧
    j.val / d = i.val / d

/-- A Boolean coordinate viewed as a real treatment indicator. -/
def blockInd {d : ℕ} (z : Fin d → Bool) (j : Fin d) : ℝ :=
  if z j then 1 else 0

/-- Clip a scalar to `[-radius,radius]`. -/
def clipTo (radius x : ℝ) : ℝ :=
  max (-radius) (min radius x)

/-- The all-one versus all-zero functional. -/
def contrastFunctional {d : ℕ} (f : (Fin d → Bool) → ℝ) : ℝ :=
  f (fun _ => true) - f (fun _ => false)

/-- Turn a model's decidable relation into estimator data. -/
def edgeFn (M : ModelClass V d β B) : V → V → Bool :=
  fun j i => @decide (M.edge j i) (M.decEdge j i)

/-- The same graph encoding for the bounded-outcome class. -/
def edgeFnBdd (M : BddOutcomeModelClass V d β B) : V → V → Bool :=
  fun j i => @decide (M.edge j i) (M.decEdge j i)

/-- A Boolean graph's in-neighborhood. -/
def nbhdB (G : V → V → Bool) (i : V) : Finset V :=
  Finset.univ.filter (fun j => G j i)
